```ts
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import fs from "node:fs/promises";
import path from "node:path";
import { isRecord } from "@openclaw/normalization-core/record-coerce";
import { test } from "vitest";
import { OpenClawSchema } from "../../src/config/zod-schema.js";
import type { GatewayClient } from "../../src/gateway/client.js";
import { acquireGatewayTestClient } from "../helpers/gateway-client.js";
import { createOpenClawTestInstance } from "../helpers/openclaw-test-instance.js";

test("real packaged Gateway persists, rearms, and admits saved automatic schedules", async ({ signal }) => {
  const proofRoot = path.resolve(".openclaw/tmp/real-gateway-proof");
  const packageRoot = path.join(proofRoot, "npm/lib/node_modules/openclaw");
  const build = JSON.parse(await fs.readFile(path.join(packageRoot, "dist/build-info.json"), "utf8"));
  assert.equal(build.commit, "0bbae0204077eab8be112ed988599f6ca0af8bd6");
  const profile = "schedule-proof-0bbae0";
  const fixture = await createOpenClawTestInstance({
    name: profile,
    cwd: packageRoot,
    entrypoint: [path.join(packageRoot, "openclaw.mjs"), "--profile", profile],
    config: {
      update: { channel: "stable", auto: { enabled: true } },
      messages: { responsePrefix: "[schedule-preservation-proof]" },
    },
    env: {
      OPENCLAW_PROFILE: profile,
      OPENCLAW_GATEWAY_URL: undefined,
      OPENCLAW_GATEWAY_PORT: undefined,
      OPENCLAW_NO_AUTO_UPDATE: undefined,
      OPENCLAW_SUPERVISOR_MODE: undefined,
      OPENCLAW_TEST_MINIMAL_GATEWAY: undefined,
      NODE_ENV: "production",
      VITEST: undefined,
      GIT_CEILING_DIRECTORIES: proofRoot,
      npm_config_prefix: path.join(proofRoot, "npm"),
      NPM_CONFIG_PREFIX: path.join(proofRoot, "npm"),
      TZ: "UTC",
    },
    startTimeoutMs: 120_000,
    signal,
  });
  fixture.env.OPENCLAW_GATEWAY_PORT = String(fixture.port);
  const result: Record<string, unknown> = {
    candidate: build.commit, version: build.version, profile, timezone: "UTC",
    packageRootKind: "isolated npm prefix", cases: [],
  };
  const cases: unknown[] = [];
  result.cases = cases;
  const marker = path.join(fixture.state.workspaceDir, "preserved-user-file.txt");
  await fs.mkdir(path.dirname(marker), { recursive: true });
  await fs.writeFile(marker, "Synthetic pre-existing user workspace data.\n");
  const markerHash = async () => createHash("sha256").update(await fs.readFile(marker)).digest("hex");
  const beforeHash = await markerHash();
  const redact = (text: string) => text.replaceAll(fixture.gatewayToken, "[fixture-token]").replaceAll(fixture.hookToken, "[fixture-hook-token]");
  let client: GatewayClient | undefined;
  async function connect() {
    client = await acquireGatewayTestClient({
      url: fixture.url, token: fixture.gatewayToken,
      clientName: "gateway-client", clientVersion: "1.0.0", platform: "test",
      mode: "backend", deviceIdentity: null, scopes: ["operator.admin"], requestTimeoutMs: 10_000,
      hostDeps: { loadDeviceAuthToken: () => null, storeDeviceAuthToken: () => {}, clearDeviceAuthToken: () => {} },
    }, { timeoutMs: 15_000, timeoutMessage: "Owned Gateway client did not connect", closeMessage: "Owned Gateway client closed", signal });
  }
  async function rpc(method: string, params: Record<string, unknown> = {}) {
    assert(client);
    const value: unknown = await client.request(method, params);
    assert(isRecord(value), `${method} must return an object`);
    return value;
  }
  async function config() {
    const snapshot = await rpc("config.get");
    assert(typeof snapshot.hash === "string");
    return { hash: snapshot.hash, config: OpenClawSchema.parse(snapshot.config) };
  }
  async function patchUpdate(update: Record<string, unknown>) {
    const snapshot = await config();
    await rpc("config.patch", { baseHash: snapshot.hash, raw: JSON.stringify({ update }) });
  }
  async function waitFor(label: string, predicate: (value: Record<string, unknown>) => boolean, timeout = 30_000) {
    const deadline = Date.now() + timeout;
    let value: Record<string, unknown> = {};
    while (Date.now() < deadline) {
      signal.throwIfAborted();
      value = await rpc("update.status");
      if (predicate(value)) return value;
      await new Promise((resolve) => setTimeout(resolve, 1500));
    }
    throw new Error(`${label} was not observed: ${redact(JSON.stringify(value))}`);
  }
  let firstPid: number | undefined;
  let restartedPid: number | undefined;
  try {
    await fixture.startGateway();
    await connect();
    firstPid = fixture.child?.pid;
    const initial = await config();
    assert.equal(initial.config.update?.auto?.enabled, true);
    assert.equal(initial.config.update?.auto?.schedule, undefined);
    cases.push({ name: "legacy no-schedule configuration loads", passed: true, scheduleAbsent: true });
    const future = new Date(Date.now() + 6 * 60 * 60 * 1000);
    const futureExpr = `${future.getUTCMinutes()} ${future.getUTCHours()} * * *`;
    await patchUpdate({ channel: "beta", auto: { enabled: true, schedule: futureExpr } });
    await rpc("update.status", { refreshCheckout: true });
    const outside = await waitFor("available beta update outside the saved window", (value) => {
      return isRecord(value.updateAvailable) && value.updateAvailable.latestVersion !== build.version &&
        isRecord(value.schedule) && value.schedule.channel === "beta";
    });
    assert(isRecord(outside.schedule));
    assert.equal(outside.schedule.install && isRecord(outside.schedule.install) ? outside.schedule.install.kind : undefined, "package");
    assert.equal(outside.schedule.campaign, undefined);
    cases.push({ name: "saved schedule blocks startup/manual-refresh campaign admission with an available real beta", passed: true, schedule: futureExpr, available: outside.updateAvailable });
    await client?.stopAndWait({ timeoutMs: 5_000 });
    client = undefined;
    await fixture.stopGateway();
    await fixture.startGateway();
    await connect();
    restartedPid = fixture.child?.pid;
    assert(firstPid && restartedPid && firstPid !== restartedPid);
    const restored = await config();
    assert.equal(restored.config.update?.auto?.schedule, futureExpr);
    assert.equal(restored.config.messages?.responsePrefix, "[schedule-preservation-proof]");
    assert.equal(await markerHash(), beforeHash);
    const restarted = await rpc("update.status", { refreshCheckout: true });
    assert(isRecord(restarted.schedule));
    assert.equal(restarted.schedule.campaign, undefined);
